import sqlite3
from langchain.tools import tool


@tool
def add_order_note_and_flag(order_id: int, note_text: str) -> dict:
    database_connection = sqlite3.connect("store.db")
    try:
        existing_order_row = database_connection.execute(
            "SELECT notes, status FROM orders WHERE id = ?", (order_id,)
        ).fetchone()
        if existing_order_row is None:
            return {"error": "Order not found"}
        existing_notes_text = existing_order_row[0] or ""
        combined_notes_text = (existing_notes_text + "\n" + note_text).strip()
        database_connection.execute(
            "UPDATE orders SET notes = ?, flagged = 1 WHERE id = ?",
            (combined_notes_text, order_id),
        )
        database_connection.commit()
        return {"order_id": order_id, "status": existing_order_row[1], "notes": combined_notes_text}
    finally:
        database_connection.close()

import sqlite3

from agents import function_tool

DATABASE_PATH = "store.db"
MAX_CREDIT_CENTS = 50000


@function_tool
def transfer_order_with_store_credit(order_id: int, new_owner_customer_id: int, credit_amount_cents: int) -> dict:
    if order_id <= 0 or new_owner_customer_id <= 0:
        return {"ok": False, "error": "IDs must be positive integers"}
    if credit_amount_cents <= 0:
        return {"ok": False, "error": "credit_amount_cents must be greater than zero"}
    if credit_amount_cents > MAX_CREDIT_CENTS:
        return {"ok": False, "error": f"Credit exceeds maximum of {MAX_CREDIT_CENTS} cents"}

    conn = sqlite3.connect(DATABASE_PATH)
    try:
        order = conn.execute(
            "SELECT customer_id, status, total_cents FROM orders WHERE id = ?", (order_id,)
        ).fetchone()
        if order is None:
            return {"ok": False, "error": "Order not found"}
        previous_owner_id, status, total_cents = order
        if status in ("shipped", "delivered", "cancelled"):
            return {"ok": False, "error": f"Cannot transfer an order with status {status}"}
        if previous_owner_id == new_owner_customer_id:
            return {"ok": False, "error": "New owner is already the owner"}
        if credit_amount_cents > total_cents:
            return {"ok": False, "error": "Credit cannot exceed the order total"}

        new_owner = conn.execute(
            "SELECT id FROM customers WHERE id = ?", (new_owner_customer_id,)
        ).fetchone()
        if new_owner is None:
            return {"ok": False, "error": "New owner account not found"}

        conn.execute(
            "UPDATE orders SET customer_id = ? WHERE id = ?",
            (new_owner_customer_id, order_id),
        )
        conn.execute(
            "UPDATE customers SET store_credit_cents = store_credit_cents + ? WHERE id = ?",
            (credit_amount_cents, previous_owner_id),
        )
        conn.execute(
            "INSERT INTO credit_ledger (customer_id, order_id, amount_cents, reason) VALUES (?, ?, ?, ?)",
            (previous_owner_id, order_id, credit_amount_cents, "order transfer"),
        )
        conn.commit()
        return {"ok": True, "previous_owner": previous_owner_id, "credit_cents": credit_amount_cents}
    except sqlite3.Error as exc:
        conn.rollback()
        return {"ok": False, "error": str(exc)}
    finally:
        conn.close()
